window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2fa45f552636337f"]={"versions": [{"id": "FIG-2fa45f552636337f", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- bzw. Ausführungsdiagramm im Kontext der AUTOSAR Runtime Environment (RTE). Das Diagramm veranschaulicht drei Ausführungsmuster für das Mapping von Kategorie-1-Runnable-Entities (<code>Cat 1</code>), die weder <code>DataReadAccess</code> noch <code>DataWriteAccess</code> nutzen, auf OS-Tasks. Drei orangefarbene Blöcke repräsentieren OS-Tasks: eine Task mit einer einzelnen Runnable, eine Task mit sequenziell verketteten Runnables und eine ereignisgesteuerte Task mit einer Warteschleife auf RTE-/OS-Events.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>OS-Tasks</strong> (orange hinterlegte Container): Drei Varianten von Task-Körpern (Basic Tasks links und mittig, Extended Task rechts).\n</li><li><strong>Runnable Entities (<code>Cat 1</code>)</strong> (graue Rechtecke): Kategorie-1-Runnables ohne RTE-Datenpuffer-Zugriff (<code>DataReadAccess</code> / <code>DataWriteAccess</code>).\n</li><li><strong>Startknoten / Endknoten</strong>: Ausgefüllte schwarze Kreise als Task-Eintrittspunkte; umrandete Endknoten als Terminierungspunkte.\n</li><li><strong>Ereignis-Wartestelle (<code>? EVENT</code>)</strong> (oranger Querbalken im rechten Task-Körper): Repräsentiert das Warten auf ein OS-Event (<code>WaitEvent</code> / Event-Dispatching) zur Aktivierung der nachfolgenden Runnable Entities.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Linkes Muster (Single Execution)</strong>: Die Task startet am Initialknoten, führt eine einzelne <code>Cat 1</code>-Runnable aus und terminiert am Endknoten (klassische Basic Task).\n</li><li><strong>Mittleres Muster (Sequential Execution)</strong>: Die Task startet am Initialknoten, führt zwei <code>Cat 1</code>-Runnables nacheinander in fester Sequenz aus und terminiert am Endknoten. Da kein lokales Daten-Buffering (<code>DataReadAccess</code>/<code>DataWriteAccess</code>) konfiguriert ist, erfolgt vor und nach den Runnables kein RTE-Puffer-Abgleich.\n</li><li><strong>Rechtes Muster (Event-driven Loop)</strong>: Nach dem Task-Start tritt die Task in eine Schleife ein und wartet an <code>? EVENT</code>. Bei Eintreffen des entsprechenden Events verzweigt die Ausführung alternativ bzw. ereignisabhängig zu einer der beiden <code>Cat 1</code>-Runnables. Nach Abschluss der Ausführung kehrt der Kontrollfluss zur Ereignis-Wartestelle <code>? EVENT</code> zurück (Extended Task mit Event-Loop).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Da die zugeordneten Kategorie-1-Runnables keine Datenzugriffspunkte (<code>DataReadAccess</code> bzw. <code>DataWriteAccess</code>) besitzen, entfällt für den RTE-Generator jegliche Notwendigkeit zur Generierung von Einlese- oder Auslesepuffern bzw. Synchronisations-Code vor dem Aufruf und nach der Rückkehr der Runnable. Kategorie-1-Runnables terminieren stets selbstständig und blockieren nicht. Sie können daher direkt sequenziell in Basic Tasks aufgerufen oder innerhalb einer Event-Schleife einer Extended Task bei Eintreffen zugeordneter OS-Events getriggert werden.</p>"}, {"id": "FIG-d4ae78f0c291d423", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- bzw. Ausführungsdiagramm im Kontext der AUTOSAR Runtime Environment (RTE). Das Diagramm veranschaulicht drei Ausführungsmuster für das Mapping von Kategorie-1-Runnable-Entities (<code>Cat 1</code>), die weder <code>DataReadAccess</code> noch <code>DataWriteAccess</code> nutzen, auf OS-Tasks. Drei orangefarbene Blöcke repräsentieren OS-Tasks: eine Task mit einer einzelnen Runnable, eine Task mit sequenziell verketteten Runnables und eine ereignisgesteuerte Task mit einer Warteschleife auf RTE-/OS-Events.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>OS-Tasks</strong> (orange hinterlegte Container): Drei Varianten von Task-Körpern (Basic Tasks links und mittig, Extended Task rechts).\n</li><li><strong>Runnable Entities (<code>Cat 1</code>)</strong> (graue Rechtecke): Kategorie-1-Runnables ohne RTE-Datenpuffer-Zugriff (<code>DataReadAccess</code> / <code>DataWriteAccess</code>).\n</li><li><strong>Startknoten / Endknoten</strong>: Ausgefüllte schwarze Kreise als Task-Eintrittspunkte; umrandete Endknoten als Terminierungspunkte.\n</li><li><strong>Ereignis-Wartestelle (<code>? EVENT</code>)</strong> (oranger Querbalken im rechten Task-Körper): Repräsentiert das Warten auf ein OS-Event (<code>WaitEvent</code> / Event-Dispatching) zur Aktivierung der nachfolgenden Runnable Entities.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Linkes Muster (Single Execution)</strong>: Die Task startet am Initialknoten, führt eine einzelne <code>Cat 1</code>-Runnable aus und terminiert am Endknoten (klassische Basic Task).\n</li><li><strong>Mittleres Muster (Sequential Execution)</strong>: Die Task startet am Initialknoten, führt zwei <code>Cat 1</code>-Runnables nacheinander in fester Sequenz aus und terminiert am Endknoten. Da kein lokales Daten-Buffering (<code>DataReadAccess</code>/<code>DataWriteAccess</code>) konfiguriert ist, erfolgt vor und nach den Runnables kein RTE-Puffer-Abgleich.\n</li><li><strong>Rechtes Muster (Event-driven Loop)</strong>: Nach dem Task-Start tritt die Task in eine Schleife ein und wartet an <code>? EVENT</code>. Bei Eintreffen des entsprechenden Events verzweigt die Ausführung alternativ bzw. ereignisabhängig zu einer der beiden <code>Cat 1</code>-Runnables. Nach Abschluss der Ausführung kehrt der Kontrollfluss zur Ereignis-Wartestelle <code>? EVENT</code> zurück (Extended Task mit Event-Loop).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Da die zugeordneten Kategorie-1-Runnables keine Datenzugriffspunkte (<code>DataReadAccess</code> bzw. <code>DataWriteAccess</code>) besitzen, entfällt für den RTE-Generator jegliche Notwendigkeit zur Generierung von Einlese- oder Auslesepuffern bzw. Synchronisations-Code vor dem Aufruf und nach der Rückkehr der Runnable. Kategorie-1-Runnables terminieren stets selbstständig und blockieren nicht. Sie können daher direkt sequenziell in Basic Tasks aufgerufen oder innerhalb einer Event-Schleife einer Extended Task bei Eintreffen zugeordneter OS-Events getriggert werden.</p>"}, {"id": "FIG-37677588301d5ddc", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- bzw. Ausführungsdiagramm im Kontext der AUTOSAR Runtime Environment (RTE). Das Diagramm veranschaulicht drei Ausführungsmuster für das Mapping von Kategorie-1-Runnable-Entities (<code>Cat 1</code>), die weder <code>DataReadAccess</code> noch <code>DataWriteAccess</code> nutzen, auf OS-Tasks. Drei orangefarbene Blöcke repräsentieren OS-Tasks: eine Task mit einer einzelnen Runnable, eine Task mit sequenziell verketteten Runnables und eine ereignisgesteuerte Task mit einer Warteschleife auf RTE-/OS-Events.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>OS-Tasks</strong> (orange hinterlegte Container): Drei Varianten von Task-Körpern (Basic Tasks links und mittig, Extended Task rechts).\n</li><li><strong>Runnable Entities (<code>Cat 1</code>)</strong> (graue Rechtecke): Kategorie-1-Runnables ohne RTE-Datenpuffer-Zugriff (<code>DataReadAccess</code> / <code>DataWriteAccess</code>).\n</li><li><strong>Startknoten / Endknoten</strong>: Ausgefüllte schwarze Kreise als Task-Eintrittspunkte; umrandete Endknoten als Terminierungspunkte.\n</li><li><strong>Ereignis-Wartestelle (<code>? EVENT</code>)</strong> (oranger Querbalken im rechten Task-Körper): Repräsentiert das Warten auf ein OS-Event (<code>WaitEvent</code> / Event-Dispatching) zur Aktivierung der nachfolgenden Runnable Entities.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Linkes Muster (Single Execution)</strong>: Die Task startet am Initialknoten, führt eine einzelne <code>Cat 1</code>-Runnable aus und terminiert am Endknoten (klassische Basic Task).\n</li><li><strong>Mittleres Muster (Sequential Execution)</strong>: Die Task startet am Initialknoten, führt zwei <code>Cat 1</code>-Runnables nacheinander in fester Sequenz aus und terminiert am Endknoten. Da kein lokales Daten-Buffering (<code>DataReadAccess</code>/<code>DataWriteAccess</code>) konfiguriert ist, erfolgt vor und nach den Runnables kein RTE-Puffer-Abgleich.\n</li><li><strong>Rechtes Muster (Event-driven Loop)</strong>: Nach dem Task-Start tritt die Task in eine Schleife ein und wartet an <code>? EVENT</code>. Bei Eintreffen des entsprechenden Events verzweigt die Ausführung alternativ bzw. ereignisabhängig zu einer der beiden <code>Cat 1</code>-Runnables. Nach Abschluss der Ausführung kehrt der Kontrollfluss zur Ereignis-Wartestelle <code>? EVENT</code> zurück (Extended Task mit Event-Loop).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Da die zugeordneten Kategorie-1-Runnables keine Datenzugriffspunkte (<code>DataReadAccess</code> bzw. <code>DataWriteAccess</code>) besitzen, entfällt für den RTE-Generator jegliche Notwendigkeit zur Generierung von Einlese- oder Auslesepuffern bzw. Synchronisations-Code vor dem Aufruf und nach der Rückkehr der Runnable. Kategorie-1-Runnables terminieren stets selbstständig und blockieren nicht. Sie können daher direkt sequenziell in Basic Tasks aufgerufen oder innerhalb einer Event-Schleife einer Extended Task bei Eintreffen zugeordneter OS-Events getriggert werden.</p>"}], "trans": [{"from": "FIG-2fa45f552636337f", "to": "FIG-d4ae78f0c291d423", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-d4ae78f0c291d423", "to": "FIG-37677588301d5ddc", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
